CREATE DATABASE IF NOT EXISTS bizlens;
USE bizlens;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS businesses(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,business_name VARCHAR(160) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,business_id INT NOT NULL,name VARCHAR(160) NOT NULL,category VARCHAR(80) DEFAULT 'General',cost_price DECIMAL(12,2) NOT NULL,selling_price DECIMAL(12,2) NOT NULL,stock INT NOT NULL DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(business_id),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,business_id INT NOT NULL,name VARCHAR(120) NOT NULL,phone VARCHAR(30),email VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,business_id INT NOT NULL,customer_id INT NOT NULL,order_date DATE NOT NULL,status ENUM('completed','cancelled') DEFAULT 'completed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,order_date),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,cost_price DECIMAL(12,2) NOT NULL,selling_price DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS expense_categories(id INT AUTO_INCREMENT PRIMARY KEY,business_id INT NOT NULL,name VARCHAR(80) NOT NULL,UNIQUE KEY uq_expense_category_business_name(business_id,name),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS expenses(id INT AUTO_INCREMENT PRIMARY KEY,business_id INT NOT NULL,category_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,expense_date DATE NOT NULL,description VARCHAR(255),INDEX(business_id,expense_date),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES expense_categories(id));
